// Generated by `just generate` from `src/plugins/claudetto/slices/agents/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `agents` slice. Each handler makes no model call, so `requests` is 0.
//
// `turn.step` keeps the context and the model of each subagent.
// `tool.call` adds the report-now note one time to the result of a subagent that is over its bound,
// and denies a write of the `planner` outside the change folder of MiniSpec.
//
// `claude plugin validate` follows `$` only into a function of one file.
// For this reason, each function that touches `$` is here, and the rules are in `domain/`.

import type { EngineInterface } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import {
  type AgentState,
  contextTokens,
  reportNote,
} from "../domain/report.ts";
import { isPlanner, plannerDeny } from "../domain/scope.ts";

/** The state of each subagent by its `agentId`. */
const agents = new Map<string, AgentState>();

/** The usage of each subagent step: its context and its model. */
export const onTurnStep: Handler<"turn.step"> = async function* (_$, e, next) {
  const result = yield* next(e);
  const { agentId } = e;
  if (agentId && result.usage)
    agents.set(agentId, {
      tokens: contextTokens(result.usage),
      model: result.usage.model,
      noted: agents.get(agentId)?.noted ?? false,
    });
  return result;
};

/** True when the agent `id` has the agent type of the planner. */
const plannerOf = async ($: EngineInterface, id: string): Promise<boolean> =>
  isPlanner((await $.agent.list()).find((a) => a.id === id)?.type);

export const onToolCall: Handler<"tool.call"> = async ($, e, next) => {
  const { agentId } = e;
  if (!agentId) return next(e);
  if (await plannerOf($, agentId)) {
    const deny = plannerDeny(
      e.tool,
      "file_path" in e ? e.file_path : undefined,
      await $.session.cwd(),
    );
    if (deny !== undefined) return { deny };
  }
  const out = await next(e);
  if (out.deny !== undefined) return out;
  const state = agents.get(agentId);
  const note = state ? reportNote(state) : undefined;
  if (!state || note === undefined) return out;
  agents.set(agentId, { ...state, noted: true });
  return { ...out, context: [...(out.context ?? []), note] };
};

