// Generated by `just generate` from `src/plugins/claudetto/slices/corrections/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handler of the `corrections` slice: the `prompt.submit` hook that adds the corrections of the user to each prompt (gap I02).
// A rule that the user gave one time decays as the context grows, and a compaction can drop it.
// So the hook reads `CORRECTIONS_FILE` on each prompt of the user, and adds its last items as context that the user does not see.
// The hook reads no text of the prompt, so no natural language decides what it adds.
// A missing file, a file with no item, or a read that fails adds nothing.
// The hook asks `$.fs.exists` first, because `$.fs.read` documents no error code for a missing file.
// `claude plugin validate` follows `$` only into a function of one file,
// so each function that touches `$` is here, and the rules are in `domain/`.

import { CORRECTIONS_FILE } from "../../../kernel/paths.ts";
import type { Handler } from "../../../kernel/slice.ts";
import { correctionsContext } from "../domain/items.ts";

export const onSubmit: Handler<"prompt.submit"> = async ($, e, next) => {
  const text = await $.fs
    .exists(CORRECTIONS_FILE)
    .then((is) => (is ? $.fs.read(CORRECTIONS_FILE) : null))
    .catch(() => null);
  const context =
    typeof text === "string"
      ? correctionsContext(CORRECTIONS_FILE, text)
      : undefined;
  if (context === undefined) return next(e);
  return next({ ...e, context: [...(e.context ?? []), context] });
};

