// Generated by `just generate` from `src/plugins/claudetto/slices/repostate/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `repostate` slice. Each handler makes no model call, so `requests` is 0.
//
// `classic.SessionStart` gives Claude the git state: `git describe`, the branch, the version in the manifests, and whether its tag exists.
// `tool.check` asks before an edit of the `[Unreleased]` section of `CHANGELOG.md` when the version has no tag,
// and before a `bun`, `npm`, `pnpm`, or `yarn` command that adds a package that no lockfile and no registry has.
// `turn.complete` marks in the status line a response from a model other than the requested one.
//
// A text that names a version or a command gives a fact that these handlers read from `git` and the files, and never a choice from memory (decision D56).
// A notice for the user goes through `$.ui.log`, which the model does not read (decision D48).
// The `tool.check` hook only asks, and it keeps a deny of the engine, so it never weakens a rule of the user (decision D53).
// Every hook calls `next` first and has no catch-all, so the result of `next` stands when the hook throws after it (decision D49).
// A `catch` below names the failure that it expects: a command or a request that fails means that the fact is absent.
//
// `claude plugin validate` follows `$` only into a function of one file,
// so each function that touches `$` is here, and the rules are in `domain/`.

import type { EngineInterface } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import {
  changelogReason,
  changesUnreleased,
  isChangelog,
} from "../domain/changelog.ts";
import {
  type Add,
  addedPackages,
  mentions,
  packageReason,
  type Registry,
  registryAnswer,
  registryNotice,
  registryUrl,
} from "../domain/packages.ts";
import { isSubstitute, servedMark } from "../domain/served.ts";
import {
  existingTag,
  type Manifest,
  manifestOf,
  type RepoState,
  stateContext,
  tagNames,
} from "../domain/state.ts";
import {
  FILE_MAX_BYTES,
  GIT_TIMEOUT_MS,
  LOCKFILES,
  MANIFESTS,
  REGISTRY_TIMEOUT_MS,
} from "../limits.ts";

/** The text of `file` when it is a regular file of at most `FILE_MAX_BYTES`, else null. */
const fileText = async (
  $: EngineInterface,
  file: string,
): Promise<string | null> => {
  if (!(await $.fs.exists(file))) return null;
  const stat = await $.fs.stat(file);
  if (stat.kind !== "file" || stat.size > FILE_MAX_BYTES) return null;
  return $.fs.read(file);
};

/** The trimmed output of `git` with `args` in `cwd`, or null when `git` fails or does not run. */
const git = async (
  $: EngineInterface,
  cwd: string,
  args: readonly string[],
): Promise<string | null> => {
  try {
    const out = await $.process.run(["git", ...args], {
      cwd,
      timeoutMs: GIT_TIMEOUT_MS,
    });
    return out.exitCode === 0 ? out.stdout.trim() : null;
  } catch {
    return null;
  }
};

/** The git state of the project in `root`, or null when `root` is in no git work tree. A project with no manifest gives a state with no manifest. */
const readState = async (
  $: EngineInterface,
  root: string,
): Promise<RepoState | null> => {
  if ((await git($, root, ["rev-parse", "--is-inside-work-tree"])) !== "true")
    return null;
  const manifests: Manifest[] = [];
  for (const file of MANIFESTS) {
    const text = await fileText($, `${root}/${file}`);
    const manifest = text === null ? null : manifestOf(file, text);
    if (manifest) manifests.push(manifest);
  }
  const manifest = manifests[0] ?? null;
  const names = manifests.flatMap((m) => m.name ?? []);
  const checked = manifest ? tagNames(manifest.version, names) : [];
  const listed = checked.length
    ? await git($, root, ["tag", "--list", ...checked])
    : null;
  return {
    describe: (await git($, root, ["describe", "--tags", "--always"])) ?? "",
    branch: (await git($, root, ["branch", "--show-current"])) ?? "",
    manifest,
    files: manifests.map((m) => m.file),
    tag: listed === null ? null : existingTag(checked, listed),
    checked,
  };
};

/** The project folder: `CLAUDE_PROJECT_DIR`, or the working directory of the session. */
const projectRoot = async ($: EngineInterface): Promise<string> =>
  (await $.env.get("CLAUDE_PROJECT_DIR")) || (await $.session.cwd());

export const onStart: Handler<"classic.SessionStart"> = async ($, e, next) => {
  const result = await next(e);
  const state = await readState($, await projectRoot($));
  if (state === null) return result;
  return {
    ...result,
    additionalContext: [
      ...(result.additionalContext ?? []),
      stateContext(state),
    ],
  };
};

/** The reason to ask about an edit of `CHANGELOG.md`, or null. */
const changelogAsk = async (
  $: EngineInterface,
  tool: string,
  input: Record<string, unknown>,
  root: string,
): Promise<string | null> => {
  const file = input["file_path"];
  if (!isChangelog(file)) return null;
  const before = await fileText($, file as string);
  if (!changesUnreleased(tool, input, before)) return null;
  const state = await readState($, root);
  if (!state?.manifest || state.tag !== null) return null;
  return changelogReason(state.manifest.version, state.manifest.file);
};

/** What the registry says of `name`, or the cause when it gives no answer. A request that takes longer than `REGISTRY_TIMEOUT_MS` gives no answer. */
const registry = async (
  $: EngineInterface,
  name: string,
  signal: AbortSignal,
): Promise<{ answer: Registry } | { cause: string }> => {
  const late = $.clock
    .sleep(REGISTRY_TIMEOUT_MS, { signal })
    .then(() => "late" as const)
    .catch(() => "stopped" as const);
  try {
    const got = await Promise.race([$.http.fetch(registryUrl(name)), late]);
    if (got === "late" || got === "stopped")
      return { cause: `no answer in ${REGISTRY_TIMEOUT_MS} ms` };
    const answer = registryAnswer(got.status);
    return answer === "unknown"
      ? { cause: `status ${got.status}` }
      : { answer };
  } catch (error) {
    return { cause: error instanceof Error ? error.message : "request failed" };
  }
};

/** The reasons to ask about the package commands in `command`. A registry that gives no answer gives a notice for the user and no reason. */
const packageAsk = async (
  $: EngineInterface,
  command: string,
  root: string,
  signal: AbortSignal,
): Promise<string | null> => {
  const adds: Add[] = addedPackages(command);
  if (adds.length === 0) return null;
  const known: string[] = [];
  const locks: string[] = [];
  for (const file of [...LOCKFILES, "package.json"]) {
    const text = await fileText($, `${root}/${file}`);
    if (text === null) continue;
    known.push(text);
    if (file !== "package.json") locks.push(`\`${file}\``);
  }
  const lockfile = locks.length ? locks.join(", ") : "none";
  const reasons: string[] = [];
  const unreached = new Map<string, string>();
  for (const add of adds) {
    const missing: string[] = [];
    for (const name of add.names) {
      if (known.some((text) => mentions(text, name))) continue;
      const got = await registry($, name, signal);
      if ("cause" in got) unreached.set(name, got.cause);
      else if (got.answer === "missing") missing.push(name);
    }
    if (missing.length > 0) reasons.push(packageReason(add, missing, lockfile));
  }
  for (const [name, cause] of unreached)
    $.ui.log(registryNotice([name], cause));
  return reasons.length > 0 ? reasons.join("\n\n") : null;
};

/** The own reason to ask, or null. A call that no rule here covers reads no fact of the session. */
const ownAsk = async (
  $: EngineInterface,
  tool: string,
  input: Record<string, unknown>,
  signal: AbortSignal,
): Promise<string | null> => {
  if (tool === "Bash") {
    const command = input["command"];
    if (typeof command !== "string" || addedPackages(command).length === 0)
      return null;
    return packageAsk($, command, await projectRoot($), signal);
  }
  if (!["Edit", "Write", "MultiEdit"].includes(tool)) return null;
  if (!isChangelog(input["file_path"])) return null;
  return changelogAsk($, tool, input, await projectRoot($));
};

// The ask reason of `repostate` comes first, then the ask reason of `next`, so the ask of another slice stays.
export const onCheck: Handler<"tool.check"> = async ($, e, next) => {
  const verdict = await next(e);
  if (verdict?.decision === "deny") return verdict;
  const input = e.input as Record<string, unknown>;
  const own = await ownAsk($, e.tool, input, next.signal);
  if (!own) return verdict;
  const reason =
    verdict?.decision === "ask" && verdict.reason
      ? `${own}\n\n${verdict.reason}`
      : own;
  return { decision: "ask", reason };
};

/** True while the status line of this plugin shows the mark. */
let marked = false;

export const onTurnComplete: Handler<"turn.complete"> = async ($, e, next) => {
  const result = await next(e);
  // A subagent has its own model, and a turn with no response has no served model.
  if (e.agentId !== undefined || e.usage === undefined) return result;
  const requested = await $.session.model();
  if (isSubstitute(requested, e.usage.model)) {
    $.ui.status(servedMark(requested, e.usage.model));
    marked = true;
  } else if (marked) {
    $.ui.status(undefined);
    marked = false;
  }
  return result;
};

