// Generated by `just generate` from `src/plugins/claudetto/slices/agents/domain/report.ts`. Edit the source and run `just generate`.
// The rules of the report-now note: the context of a subagent, and the text that tells it to report.

import { parseModel } from "../../../kernel/model.ts";
import { HAIKU_CONTEXT_MAX, SUBAGENT_CONTEXT_MAX } from "../limits.ts";
import { REPORT_NOTE } from "../prompts.ts";

/** The token counts of one model request. */
export interface Usage {
  readonly input_tokens: number;
  readonly cache_creation_input_tokens: number;
  readonly cache_read_input_tokens: number;
}

/** The state of one subagent: the context of its last request, its model, and whether it got the note. */
export interface AgentState {
  readonly tokens: number;
  readonly model: string | undefined;
  readonly noted: boolean;
}

/** The context of a request: its input, cache creation, and cache read tokens. */
export const contextTokens = (usage: Usage): number =>
  usage.input_tokens +
  usage.cache_creation_input_tokens +
  usage.cache_read_input_tokens;

/** The context bound in tokens for a subagent on `model`. */
export const boundFor = (model: string | undefined): number => {
  const m = parseModel(model);
  return m?.family === "haiku" && m.major === 5 && m.minor === 5
    ? HAIKU_CONTEXT_MAX
    : SUBAGENT_CONTEXT_MAX;
};

/** The report-now note for a subagent over its bound, or undefined while its context is in the bound or after it got the note. */
export const reportNote = (state: AgentState): string | undefined => {
  const max = boundFor(state.model);
  if (state.noted || state.tokens <= max) return undefined;
  return REPORT_NOTE({ tokens: String(state.tokens), max: String(max) });
};

