  /^stylelint\.config\..+$/,
  /^\.?mypy\.ini$/,
  /^pyrightconfig\.json$/,
  /^\.flake8$/,
  /^\.pylintrc$/,
  /^\.?(?:clippy|rustfmt)\.toml$/,
  /^\.golangci\..+$/,
  /^\.shellcheckrc$/,
  /^\.rubocop\.yml$/,
  /^\.oxlintrc\.jsonc?$/,
