/** The file names of a check runner config, matched on the last path part. */
export const RUNNER_CONFIG_NAMES = [
  /^(?:vitest|jest)\.config\..+$/,
  /^pytest\.ini$/,
  /^tox\.ini$/,
  /^\.coveragerc$/,
