// Generated by `just generate` from `src/plugins/claudetto/slices/decide/domain/route.ts`. Edit the source and run `just generate`.
// The route of a decision: Jev first when the key is set, and the fallback model when Jev gives no answer.
// Each cause of the Jev failure goes to the fallback with its own cause, so the result names it.
// These functions are pure, and the providers are the ports, so a test uses fake providers.

import type { Cause, DecisionProvider, DecisionRequest } from "../ports.ts";

/** The answer of the route: the provider that answered, the text, and the cause when Jev gave no answer. */
export type Route =
  | { readonly source: "jev"; readonly text: string }
  | {
      readonly source: "fallback";
      readonly text: string;
      readonly cause: Cause;
      readonly detail?: string;
    }
  | {
      readonly source: "none";
      readonly cause: Cause;
      readonly detail?: string;
    };

/**
 * The cause of a run of the CLI, from its exit code.
 * Exit code 3 is an invalid key, 4 is an account with no balance, 2 is a usage fault, and any other code is a failure.
 * The mapping of 4 to no balance is not verified against the TypeSafe API. It is a decision of the project.
 */
export const causeOfExit = (code: number | null): Cause => {
  switch (code) {
    case 3:
      return "invalid-key";
    case 4:
      return "no-balance";
    case 2:
      return "usage";
    default:
      return "failed";
  }
};

/** The route of a request. With no Jev provider, the cause is `no-key`, and Jev is not tried. */
export const route = async (
  jev: DecisionProvider | undefined,
  fallback: DecisionProvider,
  request: DecisionRequest,
): Promise<Route> => {
  let cause: Cause = "no-key";
  let detail: { detail?: string } = {};
  if (jev) {
    const first = await jev.decide(request);
    if (first.ok) return { source: "jev", text: first.text };
    cause = first.cause;
    if (first.detail !== undefined) detail = { detail: first.detail };
  }
  const second = await fallback.decide(request);
  if (second.ok)
    return { source: "fallback", text: second.text, cause, ...detail };
  return { source: "none", cause, ...detail };
};

