// The run itself is a parameter, so a test gives a fake run, and the hooks module gives `$.process.run`.
// `$.process.run` documents no error type, so any thrown error becomes the cause `failed`, with its message as the detail.

import { parseCliOutput } from "../domain/reply.ts";
import { type CliCall, cliCall } from "../domain/request.ts";
import { causeOfExit } from "../domain/route.ts";
import { ERROR_BODY_MAX } from "../limits.ts";
import type { DecisionProvider } from "../ports.ts";

/** The fields of a finished run that the provider reads. */
export interface CliRun {
  readonly exitCode: number | null;
  readonly stdout: string;
  readonly stderr: string;
}

/** The `detail` field for an error text, cut to `ERROR_BODY_MAX` characters. No field for an empty text. */
const detailOf = (text: string): { detail?: string } => {
  const detail = text.trim().slice(0, ERROR_BODY_MAX);
  return detail === "" ? {} : { detail };
};

/** The Jev provider over `runCli`, which runs the CLI with the arguments and the stdin of one call. */
export const createJev = (
  runCli: (call: CliCall) => Promise<CliRun>,
): DecisionProvider => ({
  name: "jev",
  decide: async (request) => {
    try {
      const run = await runCli(cliCall(request));
      if (run.exitCode !== 0)
        return {
          ok: false,
          cause: causeOfExit(run.exitCode),
          ...detailOf(run.stderr),
        };
      // An exit code of 0 with a reply that does not parse is a failure of the CLI.
      const parsed = parseCliOutput(run.stdout, request);
      if (parsed) return { ok: true, ...parsed };
      return { ok: false, cause: "failed" };
    } catch (error) {
      return {
        ok: false,
        cause: "failed",
        ...detailOf(error instanceof Error ? error.message : String(error)),
      };
    }
  },
});

