// Generated by `just generate` from `src/plugins/claudetto/slices/handoff/adapters/setup.ts`. Edit the source and run `just generate`.
// The mod handlers of the managed setup help `/handoff-setup` of the `handoff` slice (spec `handoff`, "Managed setup help").
// `session.start` in `mod.ts` registers the command, and the rules are in `domain/setup.ts`.
// The handler reads the managed settings, the file of the OS, the MDM profiles, and the plan,
// and gives one `! sudo` command or the admin text.
// The warning names the plugins that `plugin.register` showed with a `session.compact` hook,
// so a plugin that loads before `claudetto` is not named.
// Each `$` call is in this file, because `$` is not followed across an import, so `plan` is a copy of the one in `mod.ts`.

import type { EngineInterface } from "claude-code";
import { CLAUDE_STATE_FILE } from "../../../kernel/paths.ts";
import type { Handler } from "../../../kernel/slice.ts";
import {
  managedPath,
  mdmProfiles,
  type Os,
  setupHelp,
} from "../domain/setup.ts";
import { SETUP_ERROR } from "../prompts.ts";

/** The plan of the organization in the state file of Claude Code, or `undefined` when the file or the key is missing. */
const plan = async ($: EngineInterface): Promise<string | undefined> => {
  const dir =
    (await $.env.get("CLAUDE_CONFIG_DIR")) ?? (await $.env.get("HOME"));
  if (dir === undefined) return undefined;
  const state = JSON.parse(await $.fs.read(`${dir}/${CLAUDE_STATE_FILE}`));
  const type = state?.["oauthAccount"]?.["organizationType"];
  return typeof type === "string" ? type : undefined;
};

/** The plugins outside the `append` tier that hook `session.compact`, as `plugin.register` shows the plugins that load after `claudetto`. */
const compactors = new Set<string>();

/** `plugin.register`: records each plugin that loses `session.compact` under the guard, for the warning of the setup help. */
export const onPluginRegister: Handler<"plugin.register"> = ($, e, next) => {
  const hooks = e.uses.events.some((p) =>
    ["session.compact", "session.*", "*"].includes(p),
  );
  if (hooks && e.tier !== "append" && e.name !== $.plugin.name)
    compactors.add(e.name);
  return next(e);
};

/** The OS of the machine: macOS when `/System/Library` exists, else Linux (WSL included). */
const osOf = async ($: EngineInterface): Promise<Os> =>
  (await $.fs.exists("/System/Library")) ? "darwin" : "linux";

/** True when an MDM profile of Claude Code exists. Only macOS has one that a file shows. */
const hasMdm = async ($: EngineInterface, os: Os) => {
  if (os !== "darwin") return false;
  const user = await $.env.get("USER");
  const found = await Promise.all(mdmProfiles(user).map((p) => $.fs.exists(p)));
  return found.includes(true);
};

/** `command.run` of `/handoff-setup`: the managed setup help. A fact that fails to read gives an error, not an offer. */
export const onSetup: Handler<"command.run"> = async ($) => {
  try {
    const os = await osOf($);
    const path = managedPath(os);
    const file = (await $.fs.exists(path))
      ? JSON.parse(await $.fs.read(path))
      : undefined;
    const machine = {
      os,
      policy: await $.settings.read({ source: "policy" }),
      file,
      plan: await plan($).catch(() => undefined),
      hasMdm: await hasMdm($, os),
      others: [...compactors],
    };
    return { text: setupHelp(machine, $.plugin.name) };
  } catch (error) {
    return {
      text: SETUP_ERROR({ error: String(error) }),
    };
  }
};

