// Generated by `just generate` from `src/plugins/claudetto/slices/policy/domain/paths.ts`. Edit the source and run `just generate`.
// The folder and path words of a command, read by their structure: the `/` parts, the `~` prefix, and the `$` of a shell expansion.
// No function here reads prose. A word is a path or it is not, by its characters and not by its meaning.

/** True when `word` holds a part that a shell expands at run time, so its value is not in the text. */
export const isDynamic = (word: string): boolean => /[$`]/.test(word);

/** The part of `word` after the first `=` of an option, such as `--out=/tmp/a`, or `word` itself. */
export const optionValue = (word: string): string =>
  word.startsWith("-") && word.includes("=")
    ? word.slice(word.indexOf("=") + 1)
    : word;

/** `word` under `dir`. An absolute word, a `~` word, and a word with no `dir` stay as they are. */
export const under = (dir: string | undefined, word: string): string => {
  if (word.startsWith("/") || word.startsWith("~") || dir === undefined)
    return normalize(word);
  return normalize(`${dir}/${word}`);
};

/** True when `path` is the verdict store, a part of it, or a folder that holds it: `.claudetto`, `.claudetto/policy`, or a glob there. */
export const touchesStore = (path: string): boolean => {
  const parts = normalize(path).split("/");
  const at = parts.indexOf(".claudetto");
  if (at < 0) return false;
  const next = parts[at + 1];
  return next === undefined || next.startsWith("policy") || /[*?[]/.test(next);
};

/** Removes the `.` and `..` parts of `path`, in the text only. A `..` that has no part before it stays. */
export const normalize = (path: string): string => {
  const abs = path.startsWith("/");
  const out: string[] = [];
  for (const part of path.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === ".." && out.length > 0 && out[out.length - 1] !== "..")
      out.pop();
    else if (part !== ".." || !abs) out.push(part);
  }
  return `${abs ? "/" : ""}${out.join("/")}`;
};

