const INPUT_SCHEMA = {
  type: "object",
  properties: {
    repo: { type: "string", description: TOOL_REPO },
    verdict: { type: "string", enum: [...VERDICTS], description: TOOL_VERDICT },
    quote: { type: "string", description: TOOL_QUOTE },
    conditions: { type: "string", description: TOOL_CONDITIONS },
    read: {
      type: "array",
