// Generated by `just generate` from `src/plugins/claudetto/slices/policy/adapters/deny.ts`. Edit the source and run `just generate`.
// The deny for a `tool.call` event: it turns the actions of the call into repositories, and asks the gate about each one.
// Only an action that reaches an upstream repository is gated: `git push`, a `gh` write, a network write, or a write by an MCP tool.
// A file edit and a local command pass, so the gate never stops work in a checkout. The verdict store is the one local thing that it keeps.
// The functions that touch `$` are in `mod.ts`, and they come here as `Deps`.

import { type Action, actionsOf } from "../domain/actions.ts";
import { mcpTargetOf } from "../domain/mcp.ts";
import { touchesStore } from "../domain/paths.ts";
import { changesMarker, pushBypassOf } from "../domain/pushbypass.ts";
import { repoOfSpec } from "../domain/remote.ts";
import { TOOL_FULL } from "../domain/tool.ts";
import type { Stored } from "../domain/verdict.ts";
import {
  ASK_ERROR,
  DENY_BYPASS,
  DENY_ERROR,
  DENY_MARKER,
  DENY_STORE,
  DENY_UNCLEAR,
} from "../prompts.ts";
import { type Run, type Target, targetOfDir, targetOfRepo } from "./target.ts";

/** The host functions that the deny needs. */
export type Deps = {
  run: Run;
  /** The session folder. */
  cwd: () => Promise<string>;
  /** The absolute form of a folder or path word. `undefined` is the session folder. */
  abs: (word: string | undefined) => Promise<string>;
  /** The target of a `git push` in the folder `dir` to `remote`. */
  push: (dir: string, remote: string | undefined) => Promise<Target | null>;
  /** The deny for an action in `target`, or `undefined`. */
  gate: (target: Target) => Promise<string | undefined>;
  /** The target of a `gh` call. */
  gh: (
    dir: string | undefined,
    spec: string | undefined,
  ) => Promise<Target | null>;
  /** A stored verdict `forbidden`, or `undefined` when there is none. */
  forbidden: () => Promise<Stored | undefined>;
  /** True when the verdict of `target` is `silent`. A target with no known verdict gives false, because `tool.call` handles it. */
  silent: (target: Target) => Promise<boolean>;
};

export type Call = { tool: string } & Record<string, unknown>;

const store = () => DENY_STORE({ tool: TOOL_FULL });

type Upstream = Exclude<Action, { kind: "store" }>;

/** The targets that an upstream action reaches, and whether the destination is unclear. */
const targetsOf = async (d: Deps, a: Upstream) => {
  const targets: (Target | null)[] = [];
  let unclear = false;
  if (a.kind === "net") {
    unclear = a.unclear;
    for (const spec of a.repos) {
      const repo = repoOfSpec(spec);
      if (repo !== undefined) targets.push(await targetOfRepo(d.run, repo));
    }
  } else {
    unclear = a.unknown;
    const dir = await d.abs(a.dir);
    if (a.kind === "push") targets.push(await d.push(dir, a.remote));
    else targets.push(await d.gh(a.dir, a.repo));
  }
  if (unclear) targets.push(await targetOfDir(d.run, await d.cwd()));
  return { targets, unclear };
};

/** The deny for one action that reaches an upstream repository. */
const denyAction = async (
  d: Deps,
  a: Upstream,
): Promise<string | undefined> => {
  const { targets, unclear } = await targetsOf(d, a);
  for (const target of targets) {
    const deny = target === null ? undefined : await d.gate(target);
    if (deny !== undefined) return deny;
  }
  if (!unclear) return undefined;
  const closed = await d.forbidden();
  return closed === undefined
    ? undefined
    : DENY_UNCLEAR({ repo: closed.repo, quote: closed.quote });
};

/** What an upstream action needs the consent of the user for. `repo` is `undefined` when the check could not find the repository. */
export type Consent = { repo: string | undefined; push: boolean };

/**
 * The consent that `a` needs, or `undefined`.
 * A target with a `silent` verdict needs it.
 * A target that the check could not find, in a folder of an external repository, needs it too, because the check cannot say that the action is safe.
 */
const consentOf = async (
  d: Deps,
  a: Upstream,
): Promise<Consent | undefined> => {
  const { targets } = await targetsOf(d, a);
  const push = a.kind === "push";
  for (const target of targets)
    if (target !== null && (await d.silent(target)))
      return { repo: target.key, push };
  if (a.kind === "net" || !targets.includes(null)) return undefined;
  const here = await targetOfDir(d.run, await d.abs(a.dir));
  return here !== null && !here.own ? { repo: undefined, push } : undefined;
};

/** The call touches the verdict store, pushes, writes with `gh`, writes to GitHub, or is an MCP write. It needs no host function. */
export const reachesOut = (e: Call): boolean => {
  const file = e["file_path"] ?? e["notebook_path"];
  if (typeof file === "string") return touchesStore(file);
  if (typeof e["command"] === "string")
    return actionsOf(e["command"]).length > 0;
  return mcpTargetOf(e.tool, e) !== undefined;
};

/** The deny for `e` when the check failed: a call that reaches out stops, and each other call passes, so a fault of the gate never stops work. */
export const denyOnError = (e: Call): string | undefined => {
  try {
    return reachesOut(e) ? DENY_ERROR : undefined;
  } catch {
    return undefined;
  }
};

/** The deny for the `tool.call` event `e`, or `undefined`. */
export const denyOf = async (d: Deps, e: Call): Promise<string | undefined> => {
  const file = e["file_path"] ?? e["notebook_path"];
  if (typeof file === "string")
    return touchesStore(await d.abs(file)) ? store() : undefined;
  if (typeof e["command"] === "string") {
    if (changesMarker(e["command"])) return DENY_MARKER;
    const bypass = pushBypassOf(e["command"]);
    if (bypass !== undefined) return DENY_BYPASS({ what: bypass });
    for (const a of actionsOf(e["command"])) {
      const deny = a.kind === "store" ? store() : await denyAction(d, a);
      if (deny !== undefined) return deny;
    }
    return undefined;
  }
  const mcp = mcpTargetOf(e.tool, e);
  if (mcp === undefined) return undefined;
  const target =
    mcp === "session"
      ? await targetOfDir(d.run, await d.cwd())
      : await targetOfRepo(d.run, mcp.repo);
  return target === null ? undefined : d.gate(target);
};

/** The consent that the first upstream action of `e` needs, or `undefined`. */
export const silentRepoOf = async (
  d: Deps,
  e: Call,
): Promise<Consent | undefined> => {
  if (typeof (e["file_path"] ?? e["notebook_path"]) === "string")
    return undefined;
  if (typeof e["command"] === "string") {
    for (const a of actionsOf(e["command"])) {
      const need = a.kind === "store" ? undefined : await consentOf(d, a);
      if (need !== undefined) return need;
    }
    return undefined;
  }
  const mcp = mcpTargetOf(e.tool, e);
  if (mcp === undefined) return undefined;
  const target =
    mcp === "session"
      ? await targetOfDir(d.run, await d.cwd())
      : await targetOfRepo(d.run, mcp.repo);
  return target !== null && (await d.silent(target))
    ? { repo: target.key, push: false }
    : undefined;
};

/**
 * The reason to ask when the check failed, else `undefined`.
 * A call that reaches out asks.
 * A call that the reader of the command cannot read asks when the session folder is in an external repository, and else it passes to the `pre-push` hook.
 */
export const askOnError = async (
  d: Deps,
  e: Call,
): Promise<string | undefined> => {
  try {
    return reachesOut(e) ? ASK_ERROR : undefined;
  } catch {
    // The call cannot be read, so the folder decides.
  }
  try {
    const here = await targetOfDir(d.run, await d.cwd());
    return here !== null && !here.own ? ASK_ERROR : undefined;
  } catch {
    return undefined;
  }
};

