// Generated by `just generate` from `src/plugins/claudetto/slices/policy/adapters/host.ts`. Edit the source and run `just generate`.
// The shared state of the `policy` slice that `mod.ts` and `mark.ts` both use: the option, the saved GitHub tokens, and the options of a process.
// It has no `$` call, because `claude plugin validate` follows `$` past an import only into a `function` declaration, and the slice uses arrow functions.
// For this reason, `mod.ts` and `mark.ts` each keep their own small functions that call `$`.

import type { PluginOptions, ProcessRunInit } from "claude-code";
import { PROCESS_TIMEOUT_MS } from "../limits.ts";
import type { Run } from "./target.ts";

/** Whether the gate is on. The `aiPolicy` option of the plugin turns it off. */
export const kept = { on: true };

/** Keeps the option for the hooks of the slice. The generated `register` calls it once. */
export const keepOptions = (options: PluginOptions): void => {
  const value = options["aiPolicy"];
  kept.on = value !== false && value !== "false";
};

/** The GitHub tokens of the process before `mark.ts` blanked them, and the number of calls that need them blank. */
export const tokens = {
  blanked: 0,
  gh: undefined as string | undefined,
  github: undefined as string | undefined,
};

/**
 * The options of a `$.process.run` call of the slice.
 * While `mark.ts` blanks the GitHub tokens of a `Bash` call, the `gh` calls of the slice get the saved tokens.
 * `gh` reads an empty token as no token, so an empty saved value lets `gh` use its stored login.
 */
export const runInit = (cwd: string | undefined): ProcessRunInit => ({
  timeoutMs: PROCESS_TIMEOUT_MS,
  ...(cwd === undefined ? {} : { cwd }),
  ...(tokens.blanked > 0
    ? { env: { GH_TOKEN: tokens.gh ?? "", GITHUB_TOKEN: tokens.github ?? "" } }
    : {}),
});

/** The result of a program that cannot start, because `$.process.run` documents no error type. */
export const NOT_RUN: Awaited<ReturnType<Run>> = {
  exitCode: 127,
  stdout: "",
  stderr: "the program did not run",
};

