// Generated by `just generate` from `src/plugins/claudetto/slices/policy/adapters/store.ts`. Edit the source and run `just generate`.
// The disk work of the verdict store: the records, the files that the `pre-push` hook reads, and the consent tokens.
// The functions take the file API as a parameter, because the `$` calls are in `mod.ts`.

import {
  flatFileOf,
  loginFileOf,
  orgsFileOf,
  tokenFileOf,
} from "../domain/mirror.ts";
import {
  fileOf,
  parseRecord,
  type Stored,
  storeDirOf,
} from "../domain/verdict.ts";
import type { Disk } from "./local.ts";

/** The file API of the store: the reads, and the write that makes the parent folders. */
export type StoreFs = Disk & {
  write: (path: string, text: string) => Promise<void>;
};

/** The stored record of `key`, or `undefined` when there is none or it is not valid. */
export const loadRecord = async (fs: StoreFs, home: string, key: string) => {
  const file = fileOf(home, key);
  return (await fs.exists(file)) ? parseRecord(await fs.read(file)) : undefined;
};

/** Stores `record`, and writes the verdict word where the hook reads it. */
export const saveRecord = async (
  fs: StoreFs,
  home: string,
  key: string,
  record: Stored,
): Promise<void> => {
  await fs.write(fileOf(home, key), JSON.stringify(record));
  await fs.write(flatFileOf(home, key), record.verdict);
};

/** Writes the login where the hook reads it. */
export const mirrorLogin = (
  fs: StoreFs,
  home: string,
  login: string,
): Promise<void> => fs.write(loginFileOf(home), login);

/** Writes the organizations that the user owns where the hook reads them, one on each line. */
export const mirrorOrgs = (
  fs: StoreFs,
  home: string,
  orgs: readonly string[],
): Promise<void> =>
  fs.write(orgsFileOf(home), orgs.map((o) => `${o}\n`).join(""));

/** Writes the time of the consent, in seconds, and gives the file. */
export const armToken = async (
  fs: StoreFs,
  home: string,
  session: string,
  key: string,
  nowMs: number,
): Promise<string> => {
  const file = tokenFileOf(home, session, key);
  await fs.write(file, String(Math.floor(nowMs / 1000)));
  return file;
};

/** Empties the token files. A mod cannot delete a file, and the hook reads an empty file as no consent. */
export const clearTokens = async (
  fs: StoreFs,
  files: Iterable<string>,
): Promise<void> => {
  for (const file of files) await fs.write(file, "");
};

/** A stored record with the verdict `forbidden`, in the store folder. */
export const forbiddenIn = async (
  fs: StoreFs,
  home: string,
): Promise<Stored | undefined> => {
  const dir = storeDirOf(home);
  if (!(await fs.exists(dir))) return undefined;
  for (const f of await fs.list(dir)) {
    if (f.kind !== "file" || !f.name.endsWith(".json")) continue;
    const r = parseRecord(await fs.read(`${dir}/${f.name}`));
    if (r?.verdict === "forbidden") return r;
  }
  return undefined;
};

/** Writes a policy file from GitHub to the cache folder, and gives its path. */
export const cacheText = async (
  fs: StoreFs,
  home: string,
  key: string,
  source: string,
  path: string,
  text: string,
): Promise<string> => {
  const safe = (s: string) => s.replace(/[^a-z0-9.-]+/gi, "_");
  const file = `${storeDirOf(home)}/cache/${safe(key)}/${safe(source)}/${path}`;
  await fs.write(file, text);
  return file;
};

